<script setup>import AppShell from'../../Layouts/AppShell.vue';import GroupNav from'../../Components/GroupNav.vue';import PageHeader from'../../Components/PageHeader.vue';import StateCard from'../../Components/StateCard.vue';import UiButton from'../../Components/UiButton.vue';import UiModal from'../../Components/UiModal.vue';import{Head,useForm,router}from'@inertiajs/vue3';import{ref}from'vue';const p=defineProps({group:Object,canManage:Boolean,folders:Array}),form=useForm({name:'',description:'',highlighted:false}),pending=ref(null);function create(){form.post(`/groups/${p.group.id}/folders`,{onSuccess:()=>form.reset()})}function remove(){router.delete(`/groups/${p.group.id}/folders/${pending.value.id}`,{onFinish:()=>pending.value=null})}</script>
<template><AppShell><Head title="Group Folders"/><GroupNav :group="group" :can-manage="canManage"/><div class="lp-page mt-6"><PageHeader eyebrow="Group Gallery" :title="`Folders · ${group.name}`" description="Folders organize photographs inside this Group. Highlighted folders remain available to partial-access participants."/><div class="mt-8 grid gap-6 xl:grid-cols-[1fr_320px]"><div><StateCard v-if="!folders.length" title="No folders" message="The Group gallery currently has no folders."/><div v-else class="grid gap-4 sm:grid-cols-2"><UiCard v-for="folder in folders" :key="folder.id"><div class="flex justify-between gap-3"><div><h2 class="font-bold">{{folder.name}}</h2><p class="mt-1 text-sm text-slate-500">{{folder.photos_count}} photos</p></div><span v-if="folder.highlighted" class="lp-badge-info">Highlights</span></div><p v-if="folder.description" class="mt-3 text-sm text-slate-600">{{folder.description}}</p><button v-if="canManage" class="btn-ghost mt-4" @click="pending=folder">Delete empty folder</button></UiCard></div></div><UiCard v-if="canManage"><h2 class="text-lg font-bold">Create folder</h2><form class="mt-5 space-y-4" @submit.prevent="create"><label class="lp-label">Name<input v-model="form.name" class="field mt-2" required><span v-if="form.errors.name" class="lp-error">{{form.errors.name}}</span></label><label class="lp-label">Description<textarea v-model="form.description" class="field mt-2"></textarea></label><label class="flex gap-3 text-sm"><input v-model="form.highlighted" type="checkbox" class="accent-indigo">Visible as Highlights</label><UiButton type="submit" :loading="form.processing">Create folder</UiButton></form></UiCard></div><UiModal :open="!!pending" title="Delete empty folder?" description="Folders containing photos cannot be deleted." @close="pending=null" @confirm="remove"/></div></AppShell></template>
